# ---------------- REPORTES: clean copy ----------------
r = r.replace("$('portfolioNote').textContent=ventasHistorial?`${activeRows.length} ${activeRows.length===1?'OP activa':'OP activas'} · saldo pendiente del periodo. Haz clic para ver ${activeRows.length===1?'la orden':'las órdenes'}.`:'No se pudo leer el saldo detallado; mostrando estimación histórica.';", "$('portfolioNote').textContent=ventasHistorial?`${activeRows.length} ${activeRows.length===1?'OP activa':'OP activas'} · saldo pendiente del periodo.`:'No se pudo leer el saldo detallado; mostrando estimación histórica.';")
