# ---------------- REPORTES: fast return cache ----------------
r = r.replace("CACHE_KEY='HOMEEASY_REPORTES_CACHE_V1';", "CACHE_KEY='HOMEEASY_REPORTES_CACHE_V1',VIEW_CACHE_KEY='HOMEEASY_REPORT_VIEW_CACHE_V2',RETURN_FLAG='HOMEEASY_REPORT_RETURNING_V1';")

bind_marker = "function bindAction(id,handler){const el=$(id);el.addEventListener('click',handler);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();handler()}})}"
cache_helpers = r'''
function saveReportSnapshot(){try{sessionStorage.setItem(VIEW_CACHE_KEY,JSON.stringify({savedAt:Date.now(),metaVentas,dataFinanzas,ventasHistorial,periodo:$('periodo').value,customStart:customStart?customStart.toISOString():null,customEnd:customEnd?customEnd.toISOString():null}))}catch(e){}}
function restoreReportSnapshot(){try{const s=JSON.parse(sessionStorage.getItem(VIEW_CACHE_KEY)||'null');if(!s||Date.now()-Number(s.savedAt||0)>10*60*1000||!s.dataFinanzas)return false;metaVentas=Number(s.metaVentas)||metaVentas;dataFinanzas=s.dataFinanzas;ventasHistorial=s.ventasHistorial||null;if(!customStart&&s.customStart){const d=new Date(s.customStart);if(!Number.isNaN(d.getTime()))customStart=d}if(!customEnd&&s.customEnd){const d=new Date(s.customEnd);if(!Number.isNaN(d.getTime()))customEnd=d}return true}catch(e){return false}}
function fastReturnRequested(){const nav=performance.getEntriesByType&&performance.getEntriesByType('navigation')[0];return sessionStorage.getItem(RETURN_FLAG)==='1'||(nav&&nav.type==='back_forward')}
function clearReturnFlag(){try{sessionStorage.removeItem(RETURN_FLAG)}catch(e){}}
function goToVentas(kind,opNumber){saveReportSnapshot();location.href=ventasUrl(kind,opNumber)}
window.addEventListener('pagehide',saveReportSnapshot);
window.addEventListener('pageshow',e=>{if(e.persisted){clearReturnFlag();setLoading(false);saveReportSnapshot()}});
'''
if cache_helpers.strip() not in r:
    if bind_marker not in r:
        raise SystemExit('bindAction marker missing')
    r = r.replace(bind_marker, bind_marker + cache_helpers, 1)

r = r.replace("lastMetrics={rg,car,activeCount:activeRows.length,winnerOp};syncReportUrl();", "lastMetrics={rg,car,activeCount:activeRows.length,winnerOp,va,vprev,ra,pct,rem,gr,vp,pagos,best,bi,winnerName,winnerAmount:w?(parseFloat(w.total)||0):0,winnerDate:w?parseDate(w.fecha):null,activeRows};syncReportUrl();saveReportSnapshot();")

old_init = "async function init(){setLoading(true);banner(false);try{await cargarMeta();const cached=await cargarFinanzas();await cargarHistorialVentas();procesar();if(!cached)banner(false)}catch(e){console.error(e);banner('error','No se pudieron cargar los datos del reporte. Revisa la conexión e inténtalo nuevamente.')}finally{setLoading(false)}}"
new_init = "async function init(opts={}){const showLoader=opts.showLoader!==false;if(showLoader)setLoading(true);banner(false);try{await cargarMeta();const cached=await cargarFinanzas();await cargarHistorialVentas();procesar();if(!cached)banner(false)}catch(e){console.error(e);banner('error','No se pudieron cargar los datos del reporte. Revisa la conexión e inténtalo nuevamente.')}finally{if(showLoader)setLoading(false)}}"
if old_init not in r:
    raise SystemExit('init marker missing')
r = r.replace(old_init, new_init, 1)

